    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 _number, uint64 _timestamp) public {
        require(true, "");
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, 1, bytes32(0), 0, bytes32(0), 0, 0) { reverted = false; } catch { reverted = true; }
