contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(
            _number != 0 &&
            _timestamp != 0 &&
            _basefee != 0 &&
            _hash != bytes32(0) &&
            _sequenceNumber != 0 &&
            _batcherHash != bytes32(0) &&
            _l1FeeOverhead != 0 &&
            _l1FeeScalar != 0,
            "values must be all nonzero"
        );
        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) { reverted = false; } catch { reverted = true; }
        assert(
            reverted &&
            c.number() == 0 &&
            c.timestamp() == 0 &&
            c.basefee() == 0 &&
            c.hash() == bytes32(0) &&
            c.sequenceNumber() == 0 &&
            c.batcherHash() == bytes32(0) &&
            c.l1FeeOverhead() == 0 &&
            c.l1FeeScalar() == 0
        );
    }
    receive() external payable {}
}
